<script setup>import {reactive,ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const feedback=reactive({}),msg=ref('');const act=f=>{const r=f();msg.value=r.message||(r.ok?'操作成功':'操作失败')}</script>
<template><section class="h5-page"><p v-if="msg" class="action-message">{{msg}}</p><article v-for="t in state.tasks" :key="t.id" class="h5-card"><header><strong>{{t.title}}</strong><span>{{t.status}}</span></header><small>{{t.assignee}} · {{t.deadline}}</small><button v-if="t.status==='待接收'" class="primary-button active" @click="act(()=>actions.acceptTask(t.id))">确认接收</button><template v-if="t.status==='执行中'"><input v-model="feedback[t.id]" placeholder="填写现场反馈"><button class="secondary-button" @click="act(()=>actions.feedbackTask(t.id,feedback[t.id]))">提交反馈</button><button class="primary-button active" @click="act(()=>actions.completeTask(t.id))">完成任务</button></template><p v-if="t.feedback">处理反馈：{{t.feedback}}</p></article><div v-if="!state.tasks.length" class="h5-card empty">当前没有待处理任务</div></section></template>
